-- Retained originals have domain owners. Only filename/offset may be relocated.
CREATE TABLE legacy_catalog_evidence (kind TEXT NOT NULL CHECK(length(kind)>0),source_id TEXT NOT NULL,reason TEXT NOT NULL,filename TEXT NOT NULL CHECK(length(filename)>0),content_digest TEXT NOT NULL CHECK(length(content_digest)=64 AND content_digest NOT GLOB '*[^0-9a-f]*'),byte_size INTEGER NOT NULL CHECK(typeof(byte_size)='integer' AND byte_size BETWEEN 1 AND 8388608),file_offset INTEGER NOT NULL CHECK(typeof(file_offset)='integer' AND file_offset>=0),format_version TEXT NOT NULL CHECK(format_version='legacy-evidence-1'),archived_at REAL NOT NULL DEFAULT (unixepoch('subsec')),resolution_status TEXT NOT NULL CHECK(resolution_status IN ('resolved','unresolved')),legacy_id INTEGER REFERENCES legacy_track_refs(legacy_id),entry_id INTEGER REFERENCES catalog_entries(id),recording_id INTEGER REFERENCES recordings(id),PRIMARY KEY(kind,source_id)) WITHOUT ROWID;
CREATE INDEX ix_legacy_catalog_evidence_file ON legacy_catalog_evidence(filename);
CREATE INDEX ix_legacy_catalog_evidence_legacy_id ON legacy_catalog_evidence(legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX ix_legacy_catalog_evidence_entry_id ON legacy_catalog_evidence(entry_id) WHERE entry_id IS NOT NULL;
CREATE INDEX ix_legacy_catalog_evidence_recording_id ON legacy_catalog_evidence(recording_id) WHERE recording_id IS NOT NULL;
CREATE TRIGGER immutable_legacy_catalog_evidence BEFORE UPDATE OF kind,source_id,reason,content_digest,byte_size,format_version,legacy_id,entry_id,recording_id,resolution_status,archived_at ON legacy_catalog_evidence BEGIN SELECT RAISE(ABORT,'Retained original is immutable'); END;
CREATE TRIGGER retained_legacy_catalog_evidence BEFORE DELETE ON legacy_catalog_evidence BEGIN SELECT RAISE(ABORT,'Legacy evidence needs an explicit retention disposition'); END;
CREATE TABLE artist_identity_evidence (kind TEXT NOT NULL CHECK(length(kind)>0),source_id TEXT NOT NULL,reason TEXT NOT NULL,filename TEXT NOT NULL CHECK(length(filename)>0),content_digest TEXT NOT NULL CHECK(length(content_digest)=64 AND content_digest NOT GLOB '*[^0-9a-f]*'),byte_size INTEGER NOT NULL CHECK(typeof(byte_size)='integer' AND byte_size BETWEEN 1 AND 8388608),file_offset INTEGER NOT NULL CHECK(typeof(file_offset)='integer' AND file_offset>=0),format_version TEXT NOT NULL CHECK(format_version='legacy-evidence-1'),archived_at REAL NOT NULL DEFAULT (unixepoch('subsec')),resolution_status TEXT NOT NULL CHECK(resolution_status IN ('resolved','unresolved')),artist_id INTEGER REFERENCES artists(id),PRIMARY KEY(kind,source_id)) WITHOUT ROWID;
CREATE INDEX ix_artist_identity_evidence_file ON artist_identity_evidence(filename);
