CREATE TABLE artist_ambiguities (artist_id INTEGER PRIMARY KEY NOT NULL REFERENCES artists(id),reason TEXT NOT NULL CHECK(reason='contextual_release_credit')) WITHOUT ROWID;
CREATE TABLE legacy_playlist_dismissals (source_ref TEXT PRIMARY KEY NOT NULL,playlist_scope_id TEXT REFERENCES playlist_scopes(ref),until REAL,resolution_status TEXT NOT NULL CHECK(resolution_status IN ('resolved','ambiguous_account','missing_scope')),CHECK((resolution_status='resolved')=(playlist_scope_id IS NOT NULL))) WITHOUT ROWID;
CREATE INDEX ix_legacy_playlist_dismissal_scope ON legacy_playlist_dismissals(playlist_scope_id) WHERE playlist_scope_id IS NOT NULL;
